import{_ as e,o as r,c as d,a3 as a}from"./chunks/framework.vNrIUzwY.js";const m=JSON.parse('{"title":"Memory budget analysis","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kilnrender.com/preview/docs-refresh/architecture/memory-budget.html"}],["meta",{"property":"og:title","content":"Memory budget analysis | Kiln"}],["meta",{"property":"og:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}],["meta",{"property":"og:url","content":"https://kilnrender.com/preview/docs-refresh/architecture/memory-budget.html"}],["meta",{"name":"twitter:title","content":"Memory budget analysis | Kiln"}],["meta",{"name":"twitter:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}]]},"headers":[],"relativePath":"architecture/memory-budget.md","filePath":"architecture/memory-budget.md"}'),o={name:"architecture/memory-budget.md"};function s(i,t,n,l,c,h){return r(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="memory-budget-analysis" tabindex="-1">Memory budget analysis <a class="header-anchor" href="#memory-budget-analysis" aria-label="Permalink to &quot;Memory budget analysis&quot;">​</a></h1><p>For a 1024 × 512 × 1024 volume with 4 LOD levels, stored in the sharded binary format, at the full <code>660³</code> atlas:</p><p><strong>8-bit volume (<code>uint8</code>):</strong></p><table tabindex="0"><thead><tr><th>Resource</th><th>Size</th><th>Notes</th></tr></thead><tbody><tr><td>Atlas texture</td><td>274 MiB</td><td>660³ × 1 byte</td></tr><tr><td>Indirection table</td><td>8 KiB</td><td>16×8×16 × 4 bytes (LOD 0 grid)</td></tr><tr><td>Brick indices (CPU)</td><td>~2 MiB</td><td>JSON with offsets/stats (sharded binary only)</td></tr><tr><td>Volume-residency resources</td><td><strong>~274 MiB</strong></td><td>Atlas + indirection table; bounded by the atlas budget, not volume size. Excludes render targets and other GPU allocations</td></tr></tbody></table><p><strong>16-bit volume (<code>uint16</code>, <code>int16</code>, <code>float32</code>):</strong></p><table tabindex="0"><thead><tr><th>Resource</th><th>Size</th><th>Notes</th></tr></thead><tbody><tr><td>Atlas texture</td><td>548 MiB</td><td>660³ × 2 bytes</td></tr><tr><td>Indirection table</td><td>8 KiB</td><td>16×8×16 × 4 bytes (LOD 0 grid)</td></tr><tr><td>Brick indices (CPU)</td><td>~2 MiB</td><td>JSON with offsets/stats (sharded binary only)</td></tr><tr><td>Volume-residency resources</td><td><strong>~548 MiB</strong></td><td>Atlas + indirection table; bounded by the atlas budget, not volume size. Excludes render targets and other GPU allocations</td></tr></tbody></table><p>The atlas is sized from the budget (default ~1.3 GiB, <code>atlasBudgetBytes</code>), not from the volume: a 10 GB volume and a 100 MB volume get the same atlas. For multichannel datasets, each channel gets its own atlas texture and the grid shrinks to stay within the budget — see <a href="/preview/docs-refresh/architecture/virtual-texturing.html#multichannel-atlas">Virtual texturing → Multichannel atlas</a>.</p>',7)])])}const b=e(o,[["render",s]]);export{m as __pageData,b as default};
